package com.primehr.rsp.screening;
import com.primehr.integration.administrative.AdministrativeRspPositionSource; import com.primehr.integration.humanresource.HumanResourcePlantillaOccupancy; import com.primehr.positionprofile.api.PositionProfileResponse; import com.primehr.positionprofile.domain.PositionProfileStatus; import com.primehr.rsp.applicant.domain.PositionApplication; import com.primehr.rsp.applicant.infrastructure.PositionApplicationRepository; import com.primehr.rsp.domain.*; import com.primehr.rsp.infrastructure.*; import com.primehr.rsp.screening.api.ScreeningCaseDtos.*; import com.primehr.rsp.screening.api.ScreeningPolicyDtos; import com.primehr.rsp.screening.application.*; import com.primehr.rsp.screening.domain.*; import com.primehr.shared.exception.*; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.security.access.AccessDeniedException; import org.springframework.test.context.ActiveProfiles; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*; import static org.assertj.core.api.Assertions.*;
@SpringBootTest @ActiveProfiles("test") @Transactional class ScreeningCaseServiceIntegrationTest {
 @Autowired ScreeningPolicyService policies; @Autowired ScreeningCaseService cases; @Autowired ScreeningWithdrawalCoordinator withdrawal; @Autowired RecruitmentPlanRepository plans; @Autowired VacancyRequestRepository vacancies; @Autowired VacancyPublicationRepository publications; @Autowired PositionApplicationRepository applications;
 @Test void qualifiedLifecycleEnforcesAssignmentSeparationEvidenceAndSafeOutcome(){Fixture f=fixture("QUAL");CaseResponse opened=cases.open("TEST-AGENCY",f.application.getId(),new OpenCase(f.application.getVersion(),"SCREEN-1","VALID-1"),"COORD-1","open");assertThat(opened.status()).isEqualTo("DRAFT");assertThat(opened.assignments()).extracting(Assignment::employeeNo).containsExactlyInAnyOrder("SCREEN-1","VALID-1");assertThatThrownBy(()->cases.get("TEST-AGENCY",opened.id(),"UNASSIGNED",false)).isInstanceOf(AccessDeniedException.class);Finding criterion=opened.findings().get(0);CaseResponse found=cases.finding("TEST-AGENCY",opened.id(),criterion.criterionId(),new SaveFinding(opened.recordVersion(),criterion.recordVersion(),"MET","Exact evidence confirmed",List.of(new Evidence("STAFF_DECLARATION","DECL-1","Verified declaration","Reviewed immutable qualification and profile snapshots"))),"SCREEN-1","finding");CaseResponse submitted=cases.submit("TEST-AGENCY",opened.id(),new Submit(found.recordVersion(),"QUALIFIED",null,null,"Your application met the initial screening requirements."),"SCREEN-1","submit");assertThatThrownBy(()->cases.finalizeCase("TEST-AGENCY",opened.id(),new Finalize(submitted.recordVersion()),"SCREEN-1","bad-sod")).isInstanceOf(AccessDeniedException.class);CaseResponse finalCase=cases.finalizeCase("TEST-AGENCY",opened.id(),new Finalize(submitted.recordVersion()),"VALID-1","final");assertThat(finalCase.status()).isEqualTo("QUALIFIED");assertThat(finalCase.decision().validatedBy()).isEqualTo("VALID-1");PositionApplication application=applications.findById(f.application.getId()).orElseThrow();assertThat(application.getStatus()).isEqualTo(PositionApplication.Status.QUALIFIED);assertThat(application.getSafeStatus()).isEqualTo("QUALIFIED");}
 @Test void unresolvedAndInconsistentRecommendationsFailWithoutPartialFinalization(){Fixture f=fixture("FAIL");CaseResponse opened=cases.open("TEST-AGENCY",f.application.getId(),new OpenCase(f.application.getVersion(),"SCREEN-2","VALID-2"),"COORD-2",null);assertThatThrownBy(()->cases.submit("TEST-AGENCY",opened.id(),new Submit(opened.recordVersion(),"QUALIFIED",null,null,"Qualified"),"SCREEN-2",null)).isInstanceOf(ApplicationConflictException.class).hasMessageContaining("resolved");Finding criterion=opened.findings().get(0);CaseResponse found=cases.finding("TEST-AGENCY",opened.id(),criterion.criterionId(),new SaveFinding(opened.recordVersion(),criterion.recordVersion(),"NOT_MET","Requirement absent",List.of(new Evidence("STAFF_DECLARATION","DECL-2","Verified declaration","Exact evidence was reviewed"))),"SCREEN-2",null);assertThatThrownBy(()->cases.submit("TEST-AGENCY",opened.id(),new Submit(found.recordVersion(),"QUALIFIED",null,null,"Qualified"),"SCREEN-2",null)).isInstanceOf(ApplicationConflictException.class).hasMessageContaining("inconsistent");CaseResponse submitted=cases.submit("TEST-AGENCY",opened.id(),new Submit(found.recordVersion(),"DISQUALIFIED",f.reasonId,"Exact required evidence was not established","Not qualified"),"SCREEN-2",null);CaseResponse returned=cases.returnCase("TEST-AGENCY",opened.id(),new Transition(submitted.recordVersion(),"Recheck the exact evidence"),"VALID-2",null);assertThat(returned.status()).isEqualTo("RETURNED");}
 @Test void withdrawalCancelsOpenCaseAndStaleWritesFail(){Fixture f=fixture("WITHDRAW");CaseResponse opened=cases.open("TEST-AGENCY",f.application.getId(),new OpenCase(f.application.getVersion(),"SCREEN-3","VALID-3"),"COORD-3",null);assertThatThrownBy(()->cases.assignments("TEST-AGENCY",opened.id(),new Assignments(opened.recordVersion()+1,"SCREEN-3","VALID-3"),"COORD-3",null)).isInstanceOf(OptimisticConflictException.class);withdrawal.cancelOpenCase("TEST-AGENCY",f.application.getId(),"APPLICANT","Applicant withdrew",null);assertThat(cases.get("TEST-AGENCY",opened.id(),"SCREEN-3",false).status()).isEqualTo("CANCELLED");}
 private Fixture fixture(String suffix){VacancyPublication publication=publication(suffix);ScreeningPolicyDtos.SavePolicy save=new ScreeningPolicyDtos.SavePolicy("POL-"+suffix,"Policy "+suffix,null,null,null,List.of(new ScreeningPolicyDtos.CriterionInput("QS","Qualification standard","Review exact evidence","Evidence is reviewed",ScreeningCriterion.Category.EDUCATION,ScreeningCriterion.EvaluationMode.MANUAL_REVIEW,null,null,null,true,true,false,true,true,0)),List.of(new ScreeningPolicyDtos.ReasonInput("QS-NOT-MET","QS not met","One or more published requirements were not met.",ScreeningReasonCode.Outcome.DISQUALIFIED,true,0)),null);var draft=policies.create("TEST-AGENCY",save,null);var published=policies.publish("TEST-AGENCY",draft.id(),new ScreeningPolicyDtos.Publish(draft.recordVersion(),LocalDate.now().minusYears(1),null),null);policies.bind("TEST-AGENCY",publication.getId(),new ScreeningPolicyDtos.BindPolicy(published.id(),published.recordVersion(),publication.getVersion()),null);PositionApplication app=new PositionApplication("TEST-AGENCY","APPLICANT-"+suffix,publication,1);app.submit("ACK-"+suffix,"NOTICE",1,"{}","{}","[]","{}",Instant.now());app=applications.saveAndFlush(app);return new Fixture(app,published.reasonCodes().get(0).id());}
 private VacancyPublication publication(String suffix){RecruitmentPlan plan=new RecruitmentPlan("TEST-AGENCY","RP-"+suffix,"Plan",LocalDate.now().minusYears(1),LocalDate.now().plusYears(1),null);plan.submit("submit",Instant.now());plan.approve("approve",Instant.now());plans.saveAndFlush(plan);VacancyRequest vacancy=new VacancyRequest("TEST-AGENCY",plan,VacancyType.ACTUAL,null,null,null,null,"HIGH",null,"Required",new AdministrativeRspPositionSource(3L,"Plantilla",14L,"Accountant",19L,1L,2L,"FIN","Finance",7L,2,"Bachelor degree","8 hours","2 years","RA 1080",null,"CSC MC",LocalDate.now().minusYears(1),null,"a".repeat(64),Instant.now()),new HumanResourcePlantillaOccupancy(3L,false,null,null,"b".repeat(64),Instant.now()),new PositionProfileResponse("profile","Profile",null,PositionProfileStatus.ACTIVE,1,null,LocalDate.now().minusYears(1),null,3L,1L,"submit",Instant.now(),"approve",Instant.now(),null,List.of()));vacancy.submit("submit",Instant.now());vacancy.authorize("approve",Instant.now());vacancies.saveAndFlush(vacancy);VacancyPublication publication=new VacancyPublication("TEST-AGENCY",vacancy,VacancyVisibility.BOTH,LocalDate.now().minusDays(2),LocalDate.now().plusDays(5),"Apply","HR","Notice",Instant.now());publication.submit("submit",Instant.now());publication.approve("approve",Instant.now());publication.publish("publish",Instant.now());return publications.saveAndFlush(publication);}
 private record Fixture(PositionApplication application,String reasonId){}
}
